/// Casos inteiramente fictícios para exercitar a linha do tempo cardiológica.
/// Não são orientação clínica e não contêm contatos, identificadores ou profissionais reais.
struct SyntheticCardiologyDocument {
  let title: String
  let daysAgo: Int
  let body: String
  let isPDF: Bool
}

enum SyntheticCardiologyScenarios {
  static let patients: [SyntheticPatientScenario] = [
    SyntheticPatientScenario(name: "André Valença", age: 58, occupation: "contador", encounters: [
      SyntheticPatientEncounter(daysAgo: 420, body: "Motivo: palpitações e cansaço ao subir dois lances de escada. PA 158/96 mmHg, FC 92 bpm, peso 91,2 kg. ECG em repouso mostrou fibrilação atrial com resposta ventricular média de 108 bpm. Nega síncope ou dor torácica. Plano: encaminhar para cardiologia, solicitar hemograma, TSH, creatinina e ecocardiograma; evitar automedicação. Pendência: laudos e avaliação de risco tromboembólico."),
